<template><section class="shop-page"><header class="shop-heading"><div><span class="shop-eyebrow">SEU ACESSO</span><h1>Minha conta</h1><p>Identificação do responsável pelo estabelecimento.</p></div></header><section class="shop-panel shop-settings-panel"><h2>{{auth.userName}}</h2><p>{{auth.userEmail}}</p><dl><dt>Perfil de acesso</dt><dd>{{auth.isAdmin?'Administrador da loja':'Atendente'}}</dd><dt>Estabelecimento</dt><dd>{{shop.company?.name||'Não vinculado'}}</dd><dt>Departamentos autorizados</dt><dd class="shop-account-departments">{{auth.isAdmin?'Todos os departamentos':(auth.user?.department_ids||[]).map(id=>shop.departments.find(d=>d.id===id)?.name||'Setor indisponível').join(', ')}}</dd></dl><p v-if="auth.isTemporary" class="shop-form-note">Você está usando o administrador de demonstração local. O cadastro definitivo de acessos será preparado antes da operação com clientes reais.</p><p v-if="!auth.isAdmin" class="shop-form-note">Você pode acompanhar e responder somente às conversas dos departamentos autorizados para seu acesso.</p></section></section></template>
<script setup>import { useAuthStore } from '@/stores/auth.store';import { useShopStore } from '@/stores/shop.store';const auth=useAuthStore(),shop=useShopStore()</script>
